,"where":{"slug":"supported-platforms"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:3f95269c76dae7936e96b7f6cfeba6f6d46035ca701341b4830ef10d05aba401"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"krita"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"supported-platforms"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:cfc6dcb8aceab1982e042ea318a27744a323af5c8d4e97bd7dcb027be102cf6f"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"krita"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"trade-off-summary"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:4c9ef7b79c0f2bb6f31fbf68a6fe6a3f385b5677509f09b476c569b0059e7cd4"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"krita"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"trade-off-summary"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:5289e330b65358d2c525425ac240e10cea0d8ca4d133032a12dca571ce7d0bc6"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"krita"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"trade-off-summary"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:bd08e739085a0bd900975f173734e7924256a6eba85c557f4bc309c0ba943095"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"paint-net"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"no-subscription"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:890d2e9cf6aa076337d82c83f952abc1dfffac7bbc7b9ac02ea4706f8ce5e9a5"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"paint-net"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"no-subscription"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:8d376703d7f8