}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"trade-off-summary"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:7f03e7aff795207ecdeb456377afe28f8bef50b43d5b3243600eb54e61f29cda"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"paint-net"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"trade-off-summary"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:ac4261a43c1aa8ea1919def73518ed42db1bfe4e284c28d5816d4739a697f4ee"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"paint-net"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"trade-off-summary"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:d7f9ab67224e5e4968f7150087f28e2c804c26da01797f1e26172a5bb078c746"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"paint-net"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"trade-off-summary"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:dda7da73fc2c86d33a1f324105d25159c5b64ae52ccd7c490a11ee3e13245030"}}}}]},{"table":"product_anchor_evidence","operation":"upsert","conflictColumns":["product_id","anchor_id","relationship_type","claim_evidence_id"],"rows":[{"product_id":{"$ref":{"table":"products","where":{"slug":"gimp"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"photoshop"}}},"relationship_type":"alternative","claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:0dab1226117155a9732c853b1c930a9d52b1060a7a0f0991f99113dcad41fb01"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"gimp"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"photoshop"}}},"relationship_type":"alternative","claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:1ffe4512e17fb3e8e602c4f8fc221ece25a0036b507961e1353a29bf92bcdccb"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"gimp"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"photoshop"}}},"relationship_type":"alternative","claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:a389b44d05502c452f20ad64f077088f3efb6b90dfff0c1851ca63618d5b2e9a"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"gimp"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"photoshop"}}},"relationship_type":"alternative","claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:a3b44507e92a1fc82a3cbf894f1427bf7f5edd63833893db1cc58d637cd05388"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"gimp"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"photoshop"}}},"relationship_type":"alternative","claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:e685f1c8759add2d3c1629ba25160acd29b67adc69569df1c4cce5e5a741c4e4"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"krita"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"photoshop"}}},"relationship_type":"alternative","claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:3c417f7c14a58cf87c4dc25e791651b35f3728477ecae715e71fed5835951bf5"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"krita"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"photoshop"}}},"relationship_type":"alternative","claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:6e2d152e19d37348e31327e716b44545408f7f2624eb2aa66c814a7942465d54"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"krita"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"photoshop"}}},"relationship_type":"alternative","claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:7da143e4b45f0707e1cccb107414dfde41c53c9aba2105d59e279e45311bde2f"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"krita"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"photoshop"}}},"relationship_type":"alternative","claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:9d6b8ffea0dc770f4b53550a06d10800eb3a525eae9716a9d3057043f10d784a"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"krita"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"photoshop"}}},"relationship_type":"alternative","claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:fde663fd74c063aeaf6d1fb46170d2656778a6a1c28158892532017348db6655"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"paint-net"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"photoshop"}}},"relationship_type":"alternative","claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:86d81adc10e050e619e08d0b6a72a5c6cc70dadcbbd928e1e17ea5046a017d5b"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"paint-net"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"photoshop"}}},"relationship_type":"alternative","claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:91b426488aed9d8ebdaa23a8f9997317c6f8513db0534045f946f57489681d57"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"paint-net"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"photoshop"}}},"relationship_type":"alternative","claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:9e9df9fbcffbaf2bc70421d2f4e657e55cd88bcf835b7a20c999af7f0d86321c"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"paint-net"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"photoshop"}}},"relationship_type":"alternative","claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:a481d66db280ca51ddde8395624ddea859da2296ccde3286201b1c4e6ae9e365"}}}}]},{"table":"product_problem_evidence","operation":"upsert","conflictColumns":["product_id","problem_id","claim_evidence_id"],"rows":[]},{"table":"product_audience_evidence","operation":"upsert","conflictColumns":["product_id","audience_id","claim_evidence_id"],"rows":[]},{"table":"escape_routes","operation":"upsert","conflictColumns":["slug"],"rows":[]},{"table":"escape_route_products","operation":"upsert","conflictColumns":["escape_route_id","product_id"],"rows":[]}],"route":{"slug":"photoshop-alternatives-without-a-subscription","name":"Photoshop Alternatives Without a Subscription","description":"Desktop raster layers, painting and basic image adjustment without a required software subscription. Compare free official GIMP and Krita desktop releases and Paint.NET Classic; optional paid store distributions have separate terms. PSD exchange, camera RAW processing, print workflows and complete Photoshop feature parity are not guaranteed.","anchor_id":{"$ref":{"table":"anchors","where":{"slug":"photoshop"}}},"last_verified_at":"2026-10-12T00:00:00Z"},"priorMembers":[],"members":[{"productSlug":"gimp","position":1,"noveltyScore":0,"editorialNote":"Desktop raster layers, painting and basic image adjustment only. GIMP is reviewed for retouching and layered composition; RAW processing uses external plug-ins and native CMYK editing is outside the reviewed scope. No guarantee of full Photoshop, PSD, print-production, automation, AI or team-workflow parity."},{"productSlug":"krita","position":2,"noveltyScore":0,"editorialNote":"Desktop raster layers, painting and basic image adjustment only. Krita is reviewed primarily for illustration and digital painting, not comprehensive photographic retouching. PSD and text/layer semantics need review. No guarantee of full Photoshop, print-production, automation, AI or team-workflow parity."},{"productSlug":"paint-net","position":3,"noveltyScore":0,"editorialNote":"Desktop raster layers, painting and basic image adjustment only. Paint.NET is reviewed for Windows layers, selections, drawing and color adjustments. PDN is its native layered format; plugin formats do not prove PSD compatibility. No guarantee of full Photoshop, print-production, RAW, automation, AI or team-workflow parity."}]}$pr516_data$::jsonb;
 tbl jsonb; item jsonb; wanted jsonb; prop record; ref_where record;
 ref_id uuid; matched boolean; actual_count integer; expected_count integer;
 target_id uuid; route_id uuid; product_slug text; page jsonb;
BEGIN
 SET LOCAL lock_timeout='10s';
 PERFORM pg_advisory_xact_lock(7232003);
 LOCK TABLE software_discovery.evidence_sources, software_discovery.anchors, software_discovery.attributes, software_discovery.problems, software_discovery.audiences, software_discovery.products, software_discovery.product_attributes, software_discovery.product_anchors, software_discovery.product_problems, software_discovery.product_audiences, software_discovery.claim_evidence, software_discovery.product_attribute_evidence, software_discovery.product_anchor_evidence, software_discovery.product_problem_evidence, software_discovery.product_audience_evidence, software_discovery.escape_routes, software_discovery.escape_route_products IN SHARE ROW EXCLUSIVE MODE;
 IF (SELECT count(*) FROM software_discovery.products WHERE slug IN ('obsidian','things','omnifocus','2do','affine','anytype','appflowy') AND status='published')<>7 OR NOT EXISTS(SELECT 1 FROM software_discovery.escape_routes WHERE slug='todoist-alternatives-with-a-one-time-purchase' AND status='published' AND editorially_approved) OR NOT EXISTS(SELECT 1 FROM software_discovery.escape_routes WHERE slug='offline-notion-alternatives' AND status='published' AND editorially_approved) THEN RAISE EXCEPTION 'PR5.16 prior published state mismatch'; END IF;
 IF (SELECT count(*) FROM software_discovery.products WHERE slug IN ('gimp','krita','paint-net') AND status IN ('draft','published'))<>3 THEN RAISE EXCEPTION 'PR5.16 target lifecycle mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM software_discovery.escape_route_products m JOIN software_discovery.escape_routes r ON r.id=m.escape_route_id JOIN software_discovery.products p ON p.id=m.product_id WHERE p.slug IN ('gimp','krita','paint-net') AND r.slug<>'photoshop-alternatives-without-a-subscription' AND r.status='published' AND r.editorially_approved) THEN RAISE EXCEPTION 'PR5.16 other approved route exposure requires review'; END IF;
 FOR tbl IN SELECT value FROM jsonb_array_elements(payload->'tables') LOOP
  FOR item IN SELECT value FROM jsonb_array_elements(tbl->'rows') LOOP
   wanted=item;
   FOR prop IN SELECT key,value FROM jsonb_each(item) LOOP
    IF prop.value ? '$ref' THEN
     SELECT key,value INTO STRICT ref_where FROM jsonb_each(prop.value->'$ref'->'where');
     ref_id=NULL;
     EXECUTE format('SELECT id FROM software_discovery.%I WHERE %I=$1',prop.value->'$ref'->>'table',ref_where.key) INTO ref_id USING ref_where.value #>> '{}';
     IF ref_id IS NULL THEN RAISE EXCEPTION 'PR5.16 required reference missing'; END IF;
     wanted=jsonb_set(wanted,ARRAY[prop.key],to_jsonb(ref_id));
    END IF;
   END LOOP;
   IF tbl->>'table'='products' THEN wanted=wanted-'status'; END IF;
   EXECUTE format('SELECT EXISTS(SELECT 1 FROM software_discovery.%I c WHERE NOT EXISTS(SELECT 1 FROM jsonb_object_keys($1) k WHERE to_jsonb(c)->k IS DISTINCT FROM to_jsonb(jsonb_populate_record(NULL::software_discovery.%I,$1))->k))',tbl->>'table',tbl->>'table') INTO matched USING wanted;
   IF NOT matched THEN RAISE EXCEPTION 'PR5.16 review mismatch: %',tbl->>'table'; END IF;
  END LOOP;
  IF left(tbl->>'table',8)='product_' THEN
   FOREACH product_slug IN ARRAY ARRAY['gimp','krita','paint-net'] LOOP
    SELECT id INTO STRICT target_id FROM software_discovery.products WHERE slug=product_slug;
    SELECT count(*) INTO expected_count FROM jsonb_array_elements(tbl->'rows') r WHERE r->'product_id'->'$ref'->'where'->>'slug'=product_slug;
    EXECUTE format('SELECT count(*) FROM software_discovery.%I WHERE product_id=$1',tbl->>'table') INTO actual_count USING target_id;
    IF actual_count<>expected_count THEN RAISE EXCEPTION 'PR5.16 relationship/evidence set changed: %/%',product_slug,tbl->>'table'; END IF;
   END LOOP;
  END IF;
 END LOOP;
 SELECT id INTO STRICT ref_id FROM software_discovery.anchors WHERE slug='photoshop';
 wanted=jsonb_set(payload->'route',ARRAY['anchor_id'],to_jsonb(ref_id));
 SELECT id INTO route_id FROM software_discovery.escape_routes WHERE slug='photoshop-alternatives-without-a-subscription';
 IF route_id IS NOT NULL THEN
  SELECT EXISTS(SELECT 1 FROM software_discovery.escape_routes c WHERE c.id=route_id AND ((status='draft' AND NOT editorially_approved) OR (status='published' AND editorially_approved)) AND NOT EXISTS(SELECT 1 FROM jsonb_object_keys(wanted) k WHERE to_jsonb(c)->k IS DISTINCT FROM to_jsonb(jsonb_populate_record(NULL::software_discovery.escape_routes,wanted))->k)) INTO matched;
  IF NOT matched THEN
   IF NOT EXISTS(SELECT 1 FROM software_discovery.escape_routes c WHERE c.id=route_id AND c.status='draft' AND NOT c.editorially_approved AND c.name=payload->'priorRoute'->>'name' AND c.description=payload->'priorRoute'->>'description' AND c.anchor_id=ref_id AND c.last_verified_at=(payload->'priorRoute'->>'last_verified_at')::timestamptz) THEN RAISE EXCEPTION 'PR5.16 route metadata/approval mismatch'; END IF;
   SELECT count(*) INTO actual_count FROM software_discovery.escape_route_products WHERE escape_route_id=route_id;
   IF actual_count<>jsonb_array_length(payload->'priorMembers') THEN RAISE EXCEPTION 'PR5.16 baseline membership drift'; END IF;
   FOR item IN SELECT value FROM jsonb_array_elements(payload->'priorMembers') LOOP
    SELECT id INTO STRICT target_id FROM software_discovery.products WHERE slug=item->'product_id'->'$ref'->'where'->>'slug';
    IF NOT EXISTS(SELECT 1 FROM software_discovery.escape_route_products m WHERE escape_route_id=route_id AND product_id=target_id AND position IS NOT DISTINCT FROM (item->>'position')::integer AND novelty_score IS NOT DISTINCT FROM (item->>'novelty_score')::numeric AND relevance_score IS NOT DISTINCT FROM (item->>'relevance_score')::numeric AND constraint_fit_score IS NOT DISTINCT FROM (item->>'constraint_fit_score')::numeric AND quality_score IS NOT DISTINCT FROM (item->>'quality_score')::numeric AND editorial_note IS NOT DISTINCT FROM item->>'editorial_note') THEN RAISE EXCEPTION 'PR5.16 baseline member drift'; END IF;
   END LOOP;
   DELETE FROM software_discovery.escape_route_products WHERE escape_route_id=route_id;
   UPDATE software_discovery.escape_routes SET description=wanted->>'description',last_verified_at=(wanted->>'last_verified_at')::timestamptz,updated_at=now() WHERE id=route_id;
  END IF;
  SELECT count(*) INTO actual_count FROM software_discovery.escape_route_products WHERE escape_route_id=route_id;
  IF actual_count NOT IN (0,3) THEN RAISE EXCEPTION 'PR5.16 route membership drift'; END IF;
  IF actual_count=3 THEN
   FOR item IN SELECT value FROM jsonb_array_elements(payload->'members') LOOP
    SELECT id INTO STRICT target_id FROM software_discovery.products WHERE slug=item->>'productSlug';
    IF NOT EXISTS(SELECT 1 FROM software_discovery.escape_route_products m WHERE escape_route_id=route_id AND product_id=target_id AND position=(item->>'position')::integer AND novelty_score=0 AND relevance_score IS NULL AND constraint_fit_score IS NULL AND quality_score IS NULL AND editorial_note=item->>'editorialNote') THEN RAISE EXCEPTION 'PR5.16 member data mismatch'; END IF;
   END LOOP;
  END IF;
 ELSE
  IF payload->'priorRoute' IS NOT NULL THEN RAISE EXCEPTION 'PR5.16 baseline route missing'; END IF;
  INSERT INTO software_discovery.escape_routes(slug,name,description,anchor_id,last_verified_at) SELECT slug,name,description,anchor_id,last_verified_at FROM jsonb_populate_record(NULL::software_discovery.escape_routes,wanted) RETURNING id INTO route_id;
 END IF;
 UPDATE software_discovery.products SET status='published',updated_at=now() WHERE slug IN ('gimp','krita','paint-net') AND status='draft';
 FOR item IN SELECT value FROM jsonb_array_elements(payload->'members') LOOP
  SELECT id INTO STRICT target_id FROM software_discovery.products WHERE slug=item->>'productSlug';
  INSERT INTO software_discovery.escape_route_products(escape_route_id,product_id,position,novelty_score,editorial_note) VALUES(route_id,target_id,(item->>'position')::integer,0,item->>'editorialNote') ON CONFLICT(escape_route_id,product_id) DO NOTHING;
 END LOOP;
 UPDATE software_discovery.escape_routes SET status='published',editorially_approved=true,updated_at=now() WHERE id=route_id AND status='draft' AND NOT editorially_approved;
 FOREACH product_slug IN ARRAY ARRAY['gimp','krita','paint-net'] LOOP
  page=software_discovery.product_discovery_page(product_slug);
  IF page IS NULL OR page->>'status'<>'published' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(page->'anchors') a WHERE a->>'slug'='photoshop' AND a->>'scope'='desktop-raster-layers-painting-basic-adjustment' AND a->>'verificationStatus'='verified') THEN RAISE EXCEPTION 'PR5.16 public projection failed'; END IF;
 END LOOP;
 -- Approved apply persists atomically.
EXCEPTION WHEN SQLSTATE 'ZP516' THEN RAISE NOTICE 'PR5.16 rehearsal rolled back; no publication persisted';
END $pr516$;
